import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.BSwSpTvy.js";const u=JSON.parse('{"title":"Smart Prompt Caching","description":"","frontmatter":{},"headers":[],"relativePath":"features/prompt-caching.md","filePath":"features/prompt-caching.md"}'),n={name:"features/prompt-caching.md"};function r(o,e,h,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="smart-prompt-caching" tabindex="-1">Smart Prompt Caching <a class="header-anchor" href="#smart-prompt-caching" aria-label="Permalink to &quot;Smart Prompt Caching&quot;">​</a></h1><p>Zed Custom implements a sophisticated <strong>Smart Caching</strong> strategy designed to minimize both latency and API costs when using Anthropic&#39;s Claude models (including via Azure).</p><h2 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it Works&quot;">​</a></h2><p>The editor automatically analyzes your conversation history and strategically places <code>cache_control</code> markers on parts of the prompt that are likely to be reused in future turns. This ensures that the bulk of your context (code, logs, and previous messages) stays in the model&#39;s high-speed memory.</p><h3 id="caching-strategy" tabindex="-1">Caching Strategy <a class="header-anchor" href="#caching-strategy" aria-label="Permalink to &quot;Caching Strategy&quot;">​</a></h3><p>The &quot;Smart Caching&quot; logic follows a four-tiered approach:</p><ol><li><p><strong>System Prompt (Always Cached)</strong></p><ul><li>The core system instructions and your persona are always marked for caching. Since these never change, they are almost 100% effective at reusing the cache.</li></ul></li><li><p><strong>Interval Checkpoints (Every 15 Blocks)</strong></p><ul><li>As the conversation grows, Zed places a cache marker every 15 message blocks. This creates &quot;anchors&quot; in the timeline, ensuring that even in very long sessions, large chunks of the history remain cached.</li></ul></li><li><p><strong>Midpoint Anchoring</strong></p><ul><li>For conversations exceeding 30 messages, the midpoint is explicitly cached. This provides a stable reference point for the model to look back on, preventing &quot;cache evaporation&quot; in extremely deep threads.</li></ul></li><li><p><strong>Immediate Prefix (Second-to-Last Message)</strong></p><ul><li>The most recent context is the most valuable. Zed always caches the message immediately preceding your current input. This ensures that the &quot;immediate past&quot; is ready for instant reuse the moment you hit send.</li></ul></li></ol><h2 id="the-visual-indicators" tabindex="-1">The Visual Indicators <a class="header-anchor" href="#the-visual-indicators" aria-label="Permalink to &quot;The Visual Indicators&quot;">​</a></h2><p>When you are in a session with more than <strong>1024 tokens</strong> (Anthropic&#39;s minimum caching threshold), you will see real-time feedback in the turn stats:</p><ul><li>🟢 <strong>[X]k cached</strong>: Tokens that were reused from previous turns. You aren&#39;t being charged full price for these!</li><li>🔵 <strong>+[X]k saved</strong>: New tokens from the current turn that have been written into the cache for future use.</li></ul><h2 id="technical-implementation" tabindex="-1">Technical Implementation <a class="header-anchor" href="#technical-implementation" aria-label="Permalink to &quot;Technical Implementation&quot;">​</a></h2><p>The logic is implemented in the <code>agent</code> crate:</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// crates/agent/src/thread.rs</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CACHE_INTERVAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> usize</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ... logic for interval, midpoint, and prefix caching ...</span></span></code></pre></div><p>By ensuring that the prefix of the prompt remains largely static turn-over-turn, we maximize the <strong>Cache Hit Rate</strong>, results in near-instant responses even for 100k+ token threads.</p>`,14)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
